export type ShaderBackgroundVariant = keyof typeof specifications;
export const SHADER_BACKGROUND_VARIANTS = Object.keys(specifications) as ShaderBackgroundVariant[];
const sizingKeys = ["fit", "rotation", "scale", "offsetX", "offsetY", "originX", "originY", "worldWidth", "worldHeight"];
function compile(variant: ShaderBackgroundVariant, input: Input) {
  const spec: Spec = specifications[variant];
  const values: Input = { ...(spec.sizing === "object" ? Shaders.defaultObjectSizing : Shaders.defaultPatternSizing), ...spec.params };
  for (const [key, value] of Object.entries(input)) if (value !== undefined) values[key] = value;
  if (variant === "water") {
    values.image ??= "";
    if (input.size === undefined && input.effectScale !== undefined) values.size = 10 / 9 / input.effectScale - 1 / 9;
  }
  if (variant === "pulsing-border") for (const side of ["Left", "Right", "Top", "Bottom"]) {
    const key = `margin${side}`;
    if (input[key] === undefined && input.margin != null) values[key] = input.margin;
  }
  if (variant === "perlin-noise") for (const key of ["softness", "octaveCount", "persistence", "lacunarity"]) values[key] ??= spec.params[key];
  const fields = new Set([...sizingKeys, ...Object.keys(spec.params), ...(variant === "water" ? ["image"] : [])]);
  const uniforms: Input = {};
  for (const key of fields) {
    if (["speed", "frame", "margin"].includes(key)) continue;
    const value = values[key];
    const name = `u_${spec.names?.[key] ?? key}`;
    if (key === "colors") {
      uniforms[name] = value.map(Shaders.getShaderColorFromString);
      uniforms.u_colorsCount = value.length;
    } else if (key.startsWith("color")) uniforms[name] = Shaders.getShaderColorFromString(value);
    else if (key === "fit") uniforms[name] = (Shaders.ShaderFitOptions as Record<string, number>)[value];
    else if (spec.enums?.[key]) uniforms[name] = spec.enums[key][value];
    else uniforms[name] = value;
  }
  if (spec.noise) uniforms.u_noiseTexture = Shaders.getShaderNoiseTexture();
  return { uniforms, fragmentShader: spec.shader, speed: spec.static ? 0 : values.speed, frame: spec.static ? input.frame ?? 0 : values.frame };
}
export const shaderFactories = Object.fromEntries(SHADER_BACKGROUND_VARIANTS.map(variant => [variant, (input: Input) => compile(variant, input)])) as Record<ShaderBackgroundVariant, (input: Input) => ReturnType<typeof compile>>;

import { ShaderMount, emptyPixel, type ShaderMountUniforms } from "@paper-design/shaders";
import type { shaderFactories } from "./presets";
type Configuration = ReturnType<(typeof shaderFactories)[keyof typeof shaderFactories]>;
type Options = {
  speed: number; minPixelRatio?: number; maxPixelCount?: number;
  webGlContextAttributes?: WebGLContextAttributes; mipmaps?: string[];
};

/** One GPU owner; stale image work cannot replace the current scene. */
export function createShaderSession(reportFailure: (failed: boolean) => void) {
  let renderer: ShaderMount | undefined;
  let program: string | undefined;
  let frame: number | undefined;
  let revision = 0;
  let disposed = false;
  const assets = new Map<string, { promise: Promise<HTMLImageElement>; cancel: () => void }>();
  function image(url: string) {
    const cached = assets.get(url);
    if (cached) return cached.promise;
    const element = new Image();
    let rejectPending: (error: Error) => void = () => {};
    const promise = new Promise<HTMLImageElement>((resolve, reject) => {
      rejectPending = reject;
      element.crossOrigin = "anonymous";
      element.onload = () => { element.onload = element.onerror = null; resolve(element); };
      element.onerror = () => { element.onload = element.onerror = null; reject(new Error("Shader texture unavailable")); };
      element.src = url || emptyPixel;
    });
    const entry = { promise, cancel() {
      element.onload = element.onerror = null;
      rejectPending(new Error("Shader texture released"));
    } };
    assets.set(url, entry);
    return promise;
  }
  function releaseRenderer() { renderer?.dispose(); renderer = undefined; program = undefined; frame = undefined; }
  async function update(root: HTMLElement, config: Configuration, options: Options) {
    const token = ++revision;
    const current = () => !disposed && token === revision;
    try {
      const entries = await Promise.all(Object.entries(config.uniforms).map(async ([key, value]) => [key, typeof value === "string" ? await image(value) : value]));
      if (!current()) return;
      const uniforms = Object.fromEntries(entries) as ShaderMountUniforms;
      if (!renderer || program !== config.fragmentShader) {
        releaseRenderer();
        renderer = new ShaderMount(root, config.fragmentShader, uniforms, options.webGlContextAttributes,
          options.speed, config.frame, options.minPixelRatio, options.maxPixelCount, options.mipmaps);
        program = config.fragmentShader; frame = config.frame;
      } else {
        renderer.setUniforms(uniforms);
        renderer.setSpeed(options.speed);
        renderer.setMinPixelRatio(options.minPixelRatio);
        renderer.setMaxPixelCount(options.maxPixelCount);
        if (frame !== config.frame) { renderer.setFrame(config.frame); frame = config.frame; }
      }
      reportFailure(false);
    } catch {
      if (current()) { releaseRenderer(); reportFailure(true); }
    }
  }
  return { update, get renderer() { return renderer; }, dispose() {
    disposed = true; ++revision; releaseRenderer();
    assets.forEach(asset => asset.cancel()); assets.clear();
  } };
}

